'use strict';
const $=id=>document.getElementById(id);
let analysis=null, fixture=null, busy=false, isLocal=['127.0.0.1','localhost'].includes(location.hostname), dirtyReview=true;
const labels={included:'Included',change:'Potential change',clarify:'Clarify first'};
const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function message(text){$('message').textContent=text;}
function download(text,name,type='text/markdown'){const u=URL.createObjectURL(new Blob([text],{type}));const a=el('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let out;try{out=await r.json();}catch{throw Error('Run the downloaded local app to use live Gemma analysis.');}if(!r.ok)throw Error(out.error||'Request failed.');return out;}
function markSourcesChanged(){if(analysis){analysis=null;$('results').hidden=true;message('Sources changed. Run a fresh review; earlier selections were cleared.');}}
for(const id of ['scope','requests'])$(id).addEventListener('input',markSourcesChanged);
function decisions(){return [...$('cards').children].map(c=>({request_id:c.dataset.id,status:c.querySelector('select').value,hours:c.querySelector('input[type=number]').value,approved:c.querySelector('input[type=checkbox]').checked}));}
function priced(){const rate=Number($('rate').value);if(!Number.isFinite(rate)||rate<1||rate>10000||Math.abs(Math.round(rate*100)-rate*100)>0.000001)throw Error('Set a rate from $1 to $10,000, with at most two decimals.');let total=0,count=0;
 for(const [i,d] of decisions().entries()){const h=Number(d.hours);if(!Number.isFinite(h)||h<0||h>1000||h*4!==Math.round(h*4))throw Error('Effort must be 0–1,000 hours in quarter-hour increments.');const c=$('cards').children[i];const check=c.querySelector('input[type=checkbox]');check.disabled=d.status!=='change'||h<=0;if(check.disabled){check.checked=false;d.approved=false;}const amount=d.approved?Math.round(h*rate*100):0;c.querySelector('.card-amount').textContent=money(amount);total+=amount;if(d.approved)count++;}
 $('total').textContent=money(total);$('export').disabled=count===0||busy;return {total,count,rate};}
function update(){dirtyReview=true;try{priced();message('');}catch(e){$('export').disabled=true;message(e.message);}}
$('rate').addEventListener('input',update);
function render(a){analysis=a;dirtyReview=true;$('results').hidden=false;$('cards').replaceChildren();$('provenance').textContent=a.mode==='sample'?'GUIDED SAMPLE · NOT LIVE AI':`${a.model} · ${a.seconds}s · LIVE LOCAL RUN`;
 for(const status of ['included','change','clarify'])$('n-'+status).textContent=a.items.filter(r=>r.status===status).length;
 for(const row of a.items){const card=el('article','card');card.dataset.id=row.request_id;const head=el('div','card-header'),left=el('div');left.append(el('div','request-id',row.request_id),el('h3','',row.request_quote));head.append(left,el('span','badge '+row.status,labels[row.status]));card.append(head,el('p','reason','AI suggestion: '+row.reason));if(a.mode==='sample')card.querySelector('.reason').textContent='Walkthrough suggestion: '+row.reason;
 const evidence=el('div','evidence');if(row.scope_quotes.length){for(const q of row.scope_quotes){const p=el('p');p.append(el('strong','',q.id),document.createTextNode(q.text));evidence.append(p);}}else evidence.append(el('p','','No matching scope citation supplied. Check the full agreement.'));card.append(evidence);
 const controls=el('div','owner-controls'),sl=el('label','','Your decision'),select=el('select');select.setAttribute('aria-label',row.request_id+' owner decision');for(const key of ['included','change','clarify']){const opt=el('option','',labels[key]);opt.value=key;select.append(opt);}select.value=row.status;sl.append(select);
 const hl=el('label','','Your estimate · hours'),hours=el('input');hours.type='number';hours.min=0;hours.max=1000;hours.step=.25;hours.value='0';hours.setAttribute('aria-label',row.request_id+' estimated hours');hl.append(hours);
 const cl=el('label','check'),check=el('input');check.type='checkbox';check.disabled=true;check.setAttribute('aria-label','Include '+row.request_id+' in draft');cl.append(check,document.createTextNode('Include in draft'));const amount=el('div','card-amount',money(0));controls.append(sl,hl,cl,amount);card.append(controls);$('cards').append(card);
 for(const control of [select,hours,check])control.addEventListener('input',update);
 if(a.review){const saved=a.review.rows.find(r=>r.request_id===row.request_id);if(saved){select.value=saved.owner_status;hours.value=saved.hours;check.checked=saved.approved;}}
 }
 if(a.review)$('rate').value=a.review.rate;
 $('delete').hidden=a.mode==='sample';$('audit').textContent=a.mode==='sample'?'Guided walkthrough. Changes stay in memory and reset when you reload.':`Saved locally · Review ${a.id} · Source ${a.source_hash.slice(0,16)}…`;
 update();
}
$('sample').addEventListener('click',async()=>{if(busy)return;try{fixture=fixture||await fetch('./sample.json').then(r=>r.json());$('scope').value=fixture.scope;$('requests').value=fixture.requests;const a=structuredClone(fixture.analysis);const sl=fixture.scope.split('\n'),rl=fixture.requests.split('\n');a.items.forEach(r=>{r.request_quote=rl[Number(r.request_id.slice(1))-1];r.scope_quotes=r.scope_ids.map(id=>({id,text:sl[Number(id.slice(1))-1]}));});render(a);message('Sample loaded. Try 3 hours for booking and 2 hours for Spanish, then select both to create a $500 draft. These are illustrative owner estimates.');}catch(e){message(e.message);}});
$('analyze').addEventListener('click',async()=>{if(!isLocal){message('Live AI runs locally to keep client documents on your machine. Download the source kit below, start Ollama and run python3 server.py.');$('setup').scrollIntoView({behavior:'smooth'});return;}busy=true;$('analyze').disabled=true;$('sample').disabled=true;$('scope').disabled=true;$('requests').disabled=true;$('results').hidden=true;analysis=null;message('Gemma is reviewing your sources locally. The first run may take a few minutes.');try{const a=await api('/api/analyze',{scope:$('scope').value,requests:$('requests').value});render(a);message('Live analysis complete. Inspect each citation and set your own decisions.');}catch(e){message(e.message);}finally{busy=false;$('analyze').disabled=false;$('sample').disabled=false;$('scope').disabled=false;$('requests').disabled=false;}});
$('export').addEventListener('click',async()=>{try{const p=priced();if(!p.count)throw Error('Select at least one estimated change.');const review={rate:$('rate').value,decisions:decisions()};if(analysis.mode==='sample'){const lines=['# Sample change-order draft','','GUIDED DEMO — hand-authored decisions, not live AI. Client acceptance pending.',''];for(const d of review.decisions){if(d.approved){const row=analysis.items.find(x=>x.request_id===d.request_id);lines.push(`## ${d.request_id}`,row.request_quote,`Owner estimate: ${d.hours} hours | ${money(Math.round(Number(d.hours)*p.rate*100))}`,'');}}lines.push(`Total proposed: ${money(p.total)}`,'','Confirm timing, taxes and payment terms with your client before starting work.');download(lines.join('\n'),'scopeledger-sample-draft.md');message('Sample draft exported. No message was sent.');return;}
 $('export').disabled=true;const reviewed=await api('/api/review',{id:analysis.id,review});analysis=reviewed;dirtyReview=false;const out=await api('/api/export',{id:analysis.id});download(out.markdown,'scopeledger-change-order.md');message('Owner review saved locally and draft exported. Client acceptance is still pending.');}catch(e){message(e.message);}finally{if(analysis)try{priced();}catch{}}});
$('delete').addEventListener('click',async()=>{if(!analysis||analysis.mode==='sample')return;try{await api('/api/delete',{id:analysis.id});history.replaceState(null,'',location.pathname);analysis=null;$('results').hidden=true;message('This review and its audit events were deleted from the local database.');}catch(e){message(e.message);}});
async function init(){if(isLocal){try{const h=await api('/api/health');$('environment').textContent=`Local app connected · ${h.model} · Documents and review history are stored in local SQLite. Guided sample is available separately.`;const last=await api('/api/history');if(last.analyses.length){const a=await api('/api/analysis/'+last.analyses[0].id);$('scope').value=Object.values(a.scope).join('\n');$('requests').value=Object.values(a.requests).join('\n');render(a);message('Your most recent local review was restored.');}}catch{message('Open this app using python3 server.py for live AI. The guided sample works here.');}}}
init();
